import{c as t,Q as s,j as a,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Reduce","description":"","frontmatter":{},"headers":[{"level":1,"title":"Reduce","slug":"reduce"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/归约计算/Reduce.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/归约计算/Reduce.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/归约计算/Reduce.md"};function l(p,e,i,c,r,g){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="reduce" tabindex="-1">Reduce <a class="header-anchor" href="#reduce" aria-label="Permalink to &quot;Reduce&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>支持归约求和、归约取最大值、归约取最小值。</p><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;ReduceType type = ReduceType::SUM, typename T = DefaultType, typename U = DefaultType, MaskMergeMode mode = MaskMergeMode::ZEROING, typename S, typename V&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Reduce(S&amp; dstReg, V srcReg, MaskReg mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>type</td><td>ReduceType类型，支持SUM、MAX、MIN。 &lt;pre class=&quot;screen&quot; id=&quot;screen15472194923914&quot;&gt;enum class ReduceType { SUM = 0, MAX, MIN, };&lt;/pre&gt;</td></tr><tr><td>T</td><td>目的操作数dstReg的数据类型。 当type = ReduceType::SUM时，支持的数据类型需与源操作数srcReg匹配，匹配关系如下，下文中的数据类型匹配关系按照&lt;dstReg，srcReg&gt;的顺序排布： Ascend 950PR/Ascend 950DT，支持的数据类型为：&lt;int32_t，int16_t&gt;，&lt;int32_t，int32_t&gt;，&lt;half，half&gt;，&lt;uint32_t，uint16_t&gt;，&lt;uint32_t，uint32_t&gt;，&lt;float，float&gt;，&lt;uint64_t， uint64_t&gt;，&lt;int64_t， int64_t&gt; 当type = ReduceType::MAX或type = ReduceType::MIN时： Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t/half/int32_t/float/uint16_t/uint32_t/uint64_t/int64_t</td></tr><tr><td>U</td><td>源操作数srcReg的数据类型。 当type = ReduceType::SUM时，支持的数据类型需与目的操作数dstReg匹配。当type = ReduceType::MAX或type = ReduceType::MIN时，源操作数的数据类型和目的操作数相同。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t/half/int32_t/float/uint16_t/uint32_t/uint64_t/int64_t</td></tr><tr><td>mode</td><td>选择MERGING模式或ZEROING模式。当前仅支持ZEROING模式。 ZEROING，mask未筛选的元素在dst中置零。</td></tr><tr><td>S</td><td>目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>V</td><td>源操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数。 类型为RegTensor。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>对于归约求最大值，当所有元素均不参与计算时，将该数据类型的最小值写入dstReg，当存在多个最大值时，会将第一个最大值的索引保存在dstReg中。</li><li>对于归约求最小值，当所有元素均不参与计算时，将该数据类型的最大值写入dstReg，当存在多个最小值时，会将第一个最小值的索引保存在dstReg中。</li><li>当归约求最小值或者归约求最大值时，源操作数的数据类型和目的操作数相同。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>归约求和：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void ReduceVF(__ubuf__ T* dstAddr, __ubuf__ U* srcAddr, uint32_t count, </span></span>
<span class="line"><span> uint32_t srcRepeatSize, uint32_t dstRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dsrReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, srcAddr + i * srcRepeatSize);</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;U&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::Reduce&lt;AscendC::Reg::ReduceType::SUM&gt;(dsrReg, srcReg, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * dstRepeatSize, dsrReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>归约求最大值或者最小值</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void ReduceVF(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, srcAddr + i * oneRepeatSize);</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        // type = ReduceType::MAX</span></span>
<span class="line"><span>        AscendC::Reg::Reduce&lt;AscendC::Reg::ReduceType::MAX&gt;(dstReg, srcReg, mask);</span></span>
<span class="line"><span>        // type = ReduceType::MIN</span></span>
<span class="line"><span>        // AscendC::Reg::Reduce&lt;AscendC::Reg::ReduceType::MIN&gt;(dstReg, srcReg, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, maskReg);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,16)])])}const R=t(d,[["render",l]]);export{u as __pageData,R as default};
